{
  "vulnerable": true,
  "findings": [
    {
      "category": "C1",
      "title": "SOQL Injection",
      "severity": "High",
      "file": "AccountSearchController.cls",
      "lines": "6",
      "explanation": "The searchKey parameter is concatenated directly into a dynamic SOQL query string, which can lead to SOQL injection.",
      "remediation": "Use bind variables or String.escapeSingleQuotes to safely include user input in SOQL queries."
    },
    {
      "category": "C2",
      "title": "CRUD/FLS Violation",
      "severity": "Medium",
      "file": "AccountSearchController.cls",
      "lines": "6",
      "explanation": "The query does not enforce CRUD and FLS permissions, which can allow users to access fields they do not have permission to view.",
      "remediation": "Use WITH SECURITY_ENFORCED in the SOQL query to enforce CRUD and FLS permissions."
    }
  ]
}

{
  "vulnerable": true,
  "findings": [
    {
      "category": "C2",
      "title": "CRUD/FLS Violation",
      "severity": "Medium",
      "file": "ContactPhoneService.cls",
      "lines": "4, 6",
      "explanation": "The Apex class does not enforce CRUD and FLS permissions for the Contact object and its fields.",
      "remediation": "Use WITH USER_MODE in SOQL queries and enforce FLS for field access."
    },
    {
      "category": "C2",
      "title": "FLS Violation",
      "severity": "Medium",
      "file": "ContactPhoneService.cls",
      "lines": "4, 6",
      "explanation": "The Apex class does not validate field-level security for the Contact fields accessed and updated.",
      "remediation": "Use Security.stripInaccessible to enforce FLS for field access."
    }
  ]
}

{
  "vulnerable": true,
  "findings": [
    {
      "category": "C3",
      "title": "Sharing mode violation",
      "severity": "Medium",
      "file": "CaseHistoryController.cls",
      "lines": "class declaration",
      "explanation": "The class is declared 'without sharing', which ignores record-level sharing rules. This can lead to unauthorized access to records.",
      "remediation": "Change the class declaration to 'with sharing' to enforce record-level sharing rules."
    },
    {
      "category": "C2",
      "title": "CRUD/FLS violation",
      "severity": "Medium",
      "file": "CaseHistoryController.cls",
      "lines": "line 7",
      "explanation": "The query does not enforce CRUD and FLS checks. This can lead to unauthorized access to fields or objects.",
      "remediation": "Use WITH USER_MODE in the SOQL query to enforce CRUD and FLS checks."
    }
  ]
}

{
  "vulnerable": true,
  "findings": [
    {
      "category": "C4",
      "title": "Excessive Permissions",
      "severity": "High",
      "file": "Support_Agent_Tools.permissionset-meta.xml",
      "lines": "ModifyAllData, ViewAllData",
      "explanation": "The permission set grants Modify All Data and View All Data, which are powerful system permissions that should only be granted to administrators or integration users with a clear need.",
      "remediation": "Remove Modify All Data and View All Data from the permission set unless absolutely necessary and justified."
    }
  ]
}

{
  "vulnerable": true,
  "findings": [
    {
      "category": "C5",
      "title": "Guest user exposure",
      "severity": "High",
      "file": "Catalog Site Profile.profile-meta.xml",
      "lines": "classAccesses",
      "explanation": "The guest user profile grants access to the PublicCatalogController class, which can be called by anyone on the internet through the site's Aura endpoint.",
      "remediation": "Remove the PublicCatalogController class from the guest user profile's classAccesses, or ensure the class only returns data intended to be public and enforces USER_MODE."
    }
  ]
}
